#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "symm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <=i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Temporary accumulation buffer for one row of C.
     Its length matches the effective loop bound _PB_N so it works both
     for the default problem size and for any runtime-rescaled size
     chosen by PolyBench. */
  DATA_TYPE temp2_row[_PB_N];

  /* BLAS PARAMS
     SIDE = 'L'
     UPLO = 'L'
     =>  Form  C := alpha*A*B + beta*C
     A is MxM (symmetric, lower stored)
     B is MxN
     C is MxN

     Optimization strategy
     ----------------------
     The reference kernel is:

         for (i)
           for (j)
             temp2 = 0;
             for (k < i) {
               C[k][j] += alpha * B[i][j] * A[i][k];
               temp2   += B[k][j] * A[i][k];
             }
             C[i][j] = beta*C[i][j] + alpha*B[i][j]*A[i][i] + alpha*temp2;

     This iterates "column-wise" over C in the innermost loop (k varies
     fastest in C[k][j]), which is cache-unfriendly for row-major layout.

     We rewrite the computation for each fixed i as:

       - For 0 <= k < i:
           * C[k][:] receives a rank-1 update:
               C[k][:] += alpha * A[i][k] * B[i][:]
           * The dot-products needed for row i of C are accumulated into
               temp2_row[:], where
               temp2_row[j] = sum_{k < i} B[k][j] * A[i][k]

       - Then row i of C is updated using temp2_row[:]:

           C[i][j] = beta*C[i][j] + alpha*B[i][j]*A[i][i]
                     + alpha*temp2_row[j];

     We keep i as the outermost loop, but swap the order of the original
     j and k loops so that the innermost loop walks along the row
     dimension (j) of B and C. This gives contiguous accesses in the
     innermost loop and is much more cache- and SIMD-friendly, while
     preserving the exact per-element update order and thus the original
     numerical semantics.
  */

#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    /* Pointers to the i-th row of B and C.  Declared restrict to tell
       the compiler they do not alias any other rows. */
    DATA_TYPE * restrict Bi = B[i];
    DATA_TYPE * restrict Ci = C[i];
    const DATA_TYPE Aii = A[i][i];

    /* Initialize the accumulation buffer for this row i.
       After the k-loop below:
           temp2_row[j] = sum_{k=0}^{i-1} B[k][j] * A[i][k]
       for all j in [0, _PB_N). */
    for (j = 0; j < _PB_N; j++)
      temp2_row[j] = 0;

    /* Rank-1 style update over the strictly lower part of A.

       For each k < i:
         - aik = A[i][k] is the element of the i-th row / k-th column.
         - C[k][:] is updated with   alpha * aik * B[i][:].
         - temp2_row[:] accumulates  aik * B[k][:].

       Accesses in the innermost loop are:
         C[k][j], B[i][j], B[k][j], temp2_row[j]
       i.e., contiguous over j for all of these arrays. */
    for (k = 0; k < i; k++)
    {
      const DATA_TYPE aik = A[i][k];
      DATA_TYPE * restrict Ck = C[k];
      DATA_TYPE * restrict Bk = B[k];

      /* No loop-carried dependencies across j: each j index is
         independent, which enables vectorization. */
      for (j = 0; j < _PB_N; j++)
      {
        /* C[k][j] += alpha * B[i][j] * A[i][k]; */
        Ck[j] += alpha * Bi[j] * aik;

        /* temp2_row[j] accumulates sum_{k < i} B[k][j] * A[i][k]. */
        temp2_row[j] += Bk[j] * aik;
      }
    }

    /* Diagonal / current-row update of C.
       At this point, Ci[j] still contains the original C[i][j] value:
       no C[i][j] elements were touched in the k-loop above (it updates
       only rows 0..i-1).  This matches the reference implementation,
       where each C[i][j] is scaled by beta exactly once. */
    for (j = 0; j < _PB_N; j++)
    {
      /* C[i][j] = beta * C[i][j]
                   + alpha * B[i][j] * A[i][i]
                   + alpha * temp2_row[j]; */
      Ci[j] = beta * Ci[j] + alpha * Bi[j] * Aii + alpha * temp2_row[j];
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
