/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   ------------------
   The original kernel has the loop nest (i, j, k) and uses a scalar
   `temp2` inside the inner k-loop. That ordering causes strided
   accesses to B[k][j] and C[k][j] (poor spatial locality).

   Here we:
     * Introduce a per-column temporary array `temp2_row[j]` for each i.
     * Interchange the j and k loops for fixed i, giving the order
       (i, k, j). For each i and k<i we now update the whole row j of
       C[k][j] and accumulate temp2_row[j], both with unit-stride
       accesses.
     * Use local restrict-qualified pointers to help the compiler with
       alias analysis and vectorization.

   The transformation preserves the exact sequence of arithmetic
   operations for each C[i][j] and for each temp2 accumulation:
   for a given (i, j), the updates still occur with k increasing from
   0 to i-1, and the per-element order of updates to C is unchanged.
*/
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  /* Create local restrict-qualified views of the 2D arrays.
     POLYBENCH_2D makes these variable-length arrays; inside the
     function they decay to pointers to VLA rows, which we alias here. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;
  DATA_TYPE (*restrict C_)[n] = C;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  /* Per-column accumulator for the current row i.
     Size `n` matches the runtime problem size (and thus _PB_N). */
  DATA_TYPE temp2_row[n];

#pragma scop
  for (int i = 0; i < _PB_M; ++i)
  {
    DATA_TYPE *restrict Ci = C_[i];
    DATA_TYPE *restrict Bi = B_[i];

    /* Initialize per-column accumulators for this row i. This replaces
       the original `temp2 = 0;` done once per (i,j) pair. */
    for (int j = 0; j < _PB_N; ++j)
      temp2_row[j] = (DATA_TYPE)0;

    /* Handle the strictly lower triangular part: A[i][k] for k < i.
       Loop order: i (outer) -> k -> j (inner).
       For each fixed (i,k):
         - C[k][j] is updated across all columns j with unit stride.
         - temp2_row[j] accumulates B[k][j] * A[i][k] with unit stride.
       This is algebraically identical to the original kernel, where
       for fixed (i,j) we accumulated over k. The per-(i,j) accumulation
       order over k is preserved (k increases from 0 to i-1). */
    for (int k = 0; k < i; ++k)
    {
      DATA_TYPE aik       = A_[i][k];
      DATA_TYPE alpha_aik = alpha_ * aik;

      DATA_TYPE *restrict Ck = C_[k];
      DATA_TYPE *restrict Bk = B_[k];

#if defined(__GNUC__)
#pragma GCC ivdep
#endif
      for (int j = 0; j < _PB_N; ++j)
      {
        /* C[k][j] += alpha * B[i][j] * A[i][k]; */
        Ck[j]        += alpha_aik * Bi[j];

        /* temp2_row[j] += B[k][j] * A[i][k]; */
        temp2_row[j] += aik * Bk[j];
      }
    }

    /* Diagonal element A[i][i] contribution and final update of row i.
       Each C[i][j] is scaled by beta exactly once, and then receives
       all contributions corresponding to row i of A, just as in the
       original kernel. */
    DATA_TYPE aii = A_[i][i];

#if defined(__GNUC__)
#pragma GCC ivdep
#endif
    for (int j = 0; j < _PB_N; ++j)
    {
      Ci[j] = beta_ * Ci[j]
            + alpha_ * Bi[j] * aii
            + alpha_ * temp2_row[j];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

