/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:

   The original kernel implemented the BLAS SYMM operation

       C := alpha * A * B + beta * C

   for a symmetric matrix A stored in its lower triangular part.
   That implementation mirrors the reference BLAS algorithm, which
   is designed for column-major storage (Fortran).

   This optimized version restructures the computation to:

     - Traverse B and C with the column index (j) in the innermost
       loops, giving unit-stride memory access and enabling
       efficient SIMD vectorization on x86-64.

     - Reduce the number of loads of A by using each A[i][k]
       value to update entire rows of C and B, instead of
       reloading it for every column j.

   Mathematically, we use the symmetry of A:

       A_full[i][k] = (i >= k) ? A[i][k] : A[k][i]

   and compute

       C = beta * C + alpha * A_full * B

   without ever reading the unused upper-triangular entries
   (which are initialized to -999 and must remain unused).

   For each i we perform:
     1. Base update of row i:
        C[i,:] = beta * C[i,:] + alpha * A[i][i] * B[i,:]

     2. For each k < i, using A[i][k]:
          C[k,:] += alpha * A[i][k] * B[i,:]
          C[i,:] += alpha * A[i][k] * B[k,:]

   This is algebraically equivalent to the original kernel and
   matches the BLAS SYMM semantics.
*/
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Use local restrict-qualified views to help the compiler with
     alias analysis and vectorization. PolyBench guarantees that
     A, B and C are distinct, non-overlapping allocations. */
  DATA_TYPE (* restrict C_)[n] = C;
  DATA_TYPE (* restrict A_)[m] = A;
  DATA_TYPE (* restrict B_)[n] = B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  // BLAS PARAMS
  // SIDE = 'L'
  // UPLO = 'L'
  // =>  Form  C := alpha*A*B + beta*C
  // A is MxM, B is MxN, C is MxN.

#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    /* Cache row pointers once per i to reduce address computation. */
    DATA_TYPE * restrict C_row_i = C_[i];
    DATA_TYPE * restrict B_row_i = B_[i];

    /* Diagonal contribution for row i: alpha * A[i][i] * B[i,:] */
    const DATA_TYPE a_ii_alpha = alpha_local * A_[i][i];

    /* Base update for row i:
         C[i,j] = beta * C[i,j] + alpha * A[i][i] * B[i,j]
       This corresponds exactly to the "beta * C + diagonal term"
       part of the original kernel for row i. */
    for (j = 0; j < _PB_N; j++)
    {
      C_row_i[j] = beta_local * C_row_i[j] + a_ii_alpha * B_row_i[j];
    }

    /* Off-diagonal contributions:
         For each k < i:
           C[k,:] += alpha * A[i][k] * B[i,:]
           C[i,:] += alpha * A[i][k] * B[k,:]
       This uses only A[i][k] for k <= i (lower triangle), so the
       -999 upper-triangular filler values remain unused. */
    for (k = 0; k < i; k++)
    {
      const DATA_TYPE a_ik_alpha = alpha_local * A_[i][k];

      DATA_TYPE * restrict C_row_k = C_[k];
      DATA_TYPE * restrict B_row_k = B_[k];

      /* Innermost loop over j has unit stride in all arrays:
           - C_row_i[j], C_row_k[j]
           - B_row_i[j], B_row_k[j]
         This is cache-friendly and easy to SIMD-vectorize. */
      for (j = 0; j < _PB_N; j++)
      {
        const DATA_TYPE b_i_j = B_row_i[j];
        const DATA_TYPE b_k_j = B_row_k[j];

        C_row_k[j] += a_ik_alpha * b_i_j;
        C_row_i[j] += a_ik_alpha * b_k_j;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
