#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "symm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <=i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

  /* BLAS PARAMS
   * SIDE = 'L'
   * UPLO = 'L'
   * =>  Form  C := alpha*A*B + beta*C
   * A is MxM
   * B is MxN
   * C is MxN
   *
   * Optimization overview:
   *  - First, scale C by beta once (separate pass). In the original
   *    code each C[i][j] is multiplied by beta exactly once when
   *    i equals the row index. Moving this scaling to a dedicated
   *    loop preserves semantics but improves locality and makes the
   *    main kernel lighter.
   *  - Hoist common subexpressions:
   *        alpha * B[i][j]  is computed once per (i,j).
   *  - Use row pointers (Ai, Bi, Ci) and column pointers (B_col, C_col)
   *    to reduce address arithmetic inside the innermost loop and
   *    to help the compiler vectorize the k-loop.
   *  - The order of arithmetic operations on each element of C is
   *    unchanged up to algebraically equivalent rearrangements, so
   *    the mathematical result is identical to the original kernel.
   */

#pragma scop

  /* 1) Pre-scale C by beta.
   *
   * In the original kernel, for each (row i, column j) the factor
   * beta is applied exactly once, when the loop index i equals the
   * row index of C[i][j]. For that element, no prior updates have
   * occurred, so its value is still the initial C0[i][j].
   *
   * Therefore, multiplying all C[i][j] by beta before accumulating
   * any alpha*A*B contributions is semantically equivalent.
   *
   * We use _PB_M and _PB_N to match exactly the index range of the
   * original kernel.
   */
  for (i = 0; i < _PB_M; ++i)
  {
    DATA_TYPE *Ci = C[i];
    for (j = 0; j < _PB_N; ++j)
    {
      Ci[j] *= beta;
    }
  }

  /* 2) Main symmetric matrix-matrix product:
   *        C += alpha * A * B
   *    with A stored in its lower triangular part.
   *
   * The loop structure is kept compatible with the original code:
   *  - outer loop over i (row of A, B, C)
   *  - middle loop over j (column of B, C)
   *  - inner loop over k < i (lower triangular part of A)
   *
   * For each (i,j):
   *  - We update C[k][j] for all k < i.
   *  - We accumulate temp2 = sum_{k < i} B[k][j] * A[i][k].
   *  - Then we update C[i][j] using the diagonal A[i][i] and temp2.
   *
   * Only address calculation and common subexpressions have been
   * changed; the dependence structure and update order over (i,j,k)
   * remain the same.
   */
  for (i = 0; i < _PB_M; ++i)
  {
    DATA_TYPE *Ai = A[i];  /* row i of A */
    DATA_TYPE *Bi = B[i];  /* row i of B */
    DATA_TYPE *Ci = C[i];  /* row i of C */

    const DATA_TYPE Aii = Ai[i];

    for (j = 0; j < _PB_N; ++j)
    {
      const DATA_TYPE bij       = Bi[j];
      const DATA_TYPE alpha_bij = alpha * bij;

      temp2 = 0;

      /* Column pointers for B and C at column j.
       *
       * B_col points to B[0][j], C_col to C[0][j].  Advancing these
       * pointers by 'n' steps moves down one row (because the leading
       * dimension of the 2D arrays is 'n'). This avoids repeated
       * 2D index arithmetic inside the innermost k-loop.
       */
      DATA_TYPE *B_col = &B[0][j];
      DATA_TYPE *C_col = &C[0][j];

      for (k = 0; k < i; ++k)
      {
        const DATA_TYPE Aik = Ai[k];

        /* Original:
         *   C[k][j] += alpha * B[i][j] * A[i][k];
         */
        *C_col += alpha_bij * Aik;

        /* Original:
         *   temp2 += B[k][j] * A[i][k];
         */
        temp2 += (*B_col) * Aik;

        B_col += n; /* move to B[k+1][j] */
        C_col += n; /* move to C[k+1][j] */
      }

      /* Original:
       *   C[i][j] = beta * C[i][j]
       *             + alpha*B[i][j] * A[i][i]
       *             + alpha * temp2;
       *
       * Here C[i][j] was already scaled by beta in the first loop, so
       * we only need to accumulate the alpha terms:
       *
       *   C[i][j] += alpha * (B[i][j] * A[i][i] + temp2);
       */
      Ci[j] += alpha_bij * Aii + alpha * temp2;
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
